{
  "name": "elasticsearch",
  "displayName": "Elasticsearch",
  "description": "Retrieve detailed information about Elasticsearch indices, field mappings, shard distribution, and ES|QL search results. Also perform Query DSL searches and inspect shards via natural\u2011language MCP calls.",
  "homepage": "https://www.elastic.co",
  "logo": "logo.svg",
  "keywords": [
    "Monitoring & Analytics"
  ],
  "mcpServers": {
    "elasticsearch": {
      "command": "docker",
      "args": [
        "run",
        "-i",
        "--rm",
        "-e",
        "ES_URL",
        "-e",
        "ES_API_KEY",
        "mcp/elasticsearch",
        "stdio"
      ],
      "env": {
        "ES_URL": "${ES_URL}",
        "ES_API_KEY": "${ES_API_KEY}"
      }
    }
  }
}
